// Stand-in for `virtual:pwa-register/react` (generated by vite-plugin-pwa at build time). Tests that
// care mock it with vi.mock; every other test gets a worker that never has an update.
export function useRegisterSW() {
  return {
    needRefresh: [false, () => {}] as const,
    offlineReady: [false, () => {}] as const,
    updateServiceWorker: () => Promise.resolve(),
  };
}
